    ]);
    expect(parseT("{{this}} is a {{deletion}}\n", parserOptions)).toEqual([
        [CardType.Cloze, "{{this}} is a {{deletion}}", 0, 0],
    ]);
    expect(
        parseT(
            "some text before\n\na deletion on\nsuch {{wow}}\n\n" +
