        [CardType.Cloze, "Brazilians speak ==Portuguese==^[language]", 2, 2],
    ]);
    expect(
        parseT(
            "Brazilians speak ==Portuguese==[^1]\n\nBrazilians speak ==Portuguese==^[language][^1]",
