        lines = splitTextIntoLineArray(frontmatter);
        let foundTagHeading: boolean = false;
        for (let i = 0; i < lines.length; i++) {
            const line: string = lines[i];
            if (foundTagHeading) {
                if (line.startsWith(dataPrefix)) {
