            }
        } else {
            // Just a value, related to the last key
            const dataMatch: RegExpMatchArray = line.match(dataRegex);
            if (keyName && dataMatch) {
                const value = dataMatch[1].trim();
                if (value) {
                    valueList.push(value);
                }
            }
        }
    }
    if (keyName) {
        result.set(keyName, valueList);
    }
    return result;
}

